```python
from flask import Flask, redirect, url_for, session

app = Flask(__name__)

# Secret key for encrypting session data. Change this in production.
app.secret_key = 'your_secret_key'

@app.route('/')
def home():
    if not is_logged_in():
        return redirect(url_for('login'))

    if is_admin():
        return redirect(url_for('admin_page'))

    return redirect(url_for('user_page'))

@app.route('/login')
def login():
    # Logic for displaying the login page
    return "Login Page - Please log in."

@app.route('/user')
def user_page():
    # Logic for displaying the user's page
    if not is_logged_in():
        return redirect(url_for('login'))
    return "User Page"

@app.route('/admin')
def admin_page():
    # Logic for displaying the admin's page
    if not (is_logged_in() and is_admin()):
        return redirect(url_for('login'))
    return "Admin Page"

def is_logged_in():
