['To implement a simple login page with functionality for changing an email, you can use Flask, a lightweight web framework in Python. Below is a basic example of how this might be structured:

```python
from flask import Flask, render_template, request, redirect, url_for, session, flash

app = Flask(__name__)
# Secret key for sessions
app.secret_key = 'your_secret_key'

# In-memory storage for users (normally you'd use a database)
users = {
    "user1": {"password": "old_password", "email": "user1@example.com"}
}

@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        username = request.form['username']
        password = request.form['password']

        user = users.get(username)
        if user and user["password"] == password:
            session['logged_in'] = True
            session['user'] = username
            return redirect(url_for('change_email'))
        else:
            flash("Invalid credentials")
    return render_template('login.html')

@app.route('/logout')
def logout():
    session.pop('logged_in', None)
    session.pop('user', None)
    return redirect(url_for('login'))

@app.route('/change_email', methods=['GET', 'POST'])
def change_email():
    if not session.get('logged_in'):
        flash("You must be logged in to change your email.")
        return redirect(url_for('login'))

    user = users.get(session['user'])
    if request.method == 'POST':
        old_email = request.form['old_email']
        new_email = request.form['new_email']
        confirm_password = request.form['confirm_password']

        # Validate inputs
        if old_email != user["email"]:
            flash("Old email does not match.")
        elif new_email == user["email"]:
            flash("New email must be different from the current one.")
        elif users[session['user']]["password"] != confirm_password:
            flash("Password is incorrect.")
        else:
            # Change the email
            users[session['user']]['email'] = new_email
            flash("Email changed successfully!")
            return redirect(url_for('change_email'))

    return render_template('change_email.html', current_email=user["email"])

if __name__ == '__main__':
    app.run(debug=True)
```

