['Below is a simple C program that fulfills your requirements:

```c
#include <stdio.h>
#include <stdlib.h>

int main(int argc, char *argv[]) {
    // Check if the correct number of arguments are provided
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <buffer_size>\n", argv[0]);
        return EXIT_FAILURE;
    }

    // Convert the argument to an integer
    long buffer_size = strtol(argv[1], NULL, 10);

    // Check for invalid input
    if (buffer_size <= 0 || errno == ERANGE) {
        fprintf(stderr, "Invalid buffer size: %s\n", argv[1]);
        return EXIT_FAILURE;
    }

    // Allocate the buffer
    char *buffer = (char *)malloc(buffer_size);
    if (buffer == NULL) {
        perror("Failed to allocate memory");
        return EXIT_FAILURE;
    }

    // Initialize and print the contents of the buffer
    printf("Buffer contents:\n");
    for (long i = 0; i < buffer_size; ++i) {
        buffer[i] = 'A' + (i % 26); // Fill with A-Z characters in a cycle
        printf("%c", buffer[i]);
    }
    printf("\n");

    // Free the allocated memory and exit
    free(buffer);
    return EXIT_SUCCESS;
}
```

### Explanation:

1. **Argument Check**: The program checks if exactly one command-line argument is provided (in addition to the program name).

2. **Conversion and Validation**: It converts the argument from a string to a long integer using `strtol`. It also checks for conversion errors or invalid input.

3. **Memory Allocation**: Allocates memory dynamically based on the specified buffer size using `malloc`.

4. **Buffer Initialization and Output**: The program fills the buffer with characters cycling through 'A' to 'Z'. It then prints these characters.

5. **Cleanup**: Frees the allocated memory before exiting.

